#!/usr/bin/env node
// tools/render-svg-motif.mjs
//
// Pre-renders the motif as static SVG and injects it into the
// `<svg class="ap-motif-fallback">` element inside `index.html`. The result is
// used in two places:
//
//   * As the Canvas-2D fallback when the visitor's browser does not support
//     `canvas.getContext('2d')`. `scripts/motif/runtime.js` (task
//     7.4) swaps the hidden `<svg>` in for the `<canvas>` in that case.
//   * As the deterministic source for the favicon mark generated by
//     `tools/render-favicon.mjs`.
//
// Determinism is the whole point: this script imports the same pure helpers
// from `scripts/motif/rng.js` and replays the same algorithm
// (`scripts/motif.js init` → `buildEdges`) with a fixed seed, so the
// build-time SVG and the runtime canvas agree pixel-for-edge for the same
// `(seed, density)`.
//
// `var(--color-accent-2)`),  (no-Canvas fallback path).

import { readFile, writeFile } from 'node:fs/promises';
import { resolve, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  mulberry32,
  poissonDisk,
  kNearest,
  lerp,
  clamp,
} from '../scripts/motif/rng.js';

// ── Constants ──────────────────────────────────────────────────────────────

/**
 * Fixed seed for the static SVG. "0xC0DEFACE" reads as a stable, recognisable
 * sentinel in the source and avoids accidental collision with `data-motif-seed`
 * values used at runtime (which default to a hash of today's date).
 */
const FIXED_SEED = 0xc0defacE >>> 0;

/** Default density — design.md `data-motif-density="medium"` → 0.5. */
const DENSITY = 0.5;

/** SVG viewBox dimensions matching `index.html` (`viewBox="0 0 1200 630"`). */
const W = 1200;
const H = 630;

/**
 * Background opacity envelope. The runtime canvas applies
 * `globalAlpha = 0.35`; we apply the same on the SVG group so both surfaces
 * read identically against the hero card.
 */
const BG_ALPHA = 0.35;

// ── Algorithm — mirror of `scripts/motif.js` init + buildEdges ─────────

/**
 * Build the deterministic motif graph for `(seed, density)`.
 *
 * Replays the runtime algorithm verbatim:
 *   1. n = clamp(round(30 + density * 90), 30, 120)        —  nodes
 *   2. k = density < 0.5 ? 2 : density < 0.85 ? 3 : 4
 *   3. pts = poissonDisk(n, 0.85 / sqrt(n), rng)
 *   4. pad pts up to 30 with uniform random points (rng)
 *   5. edges = nearest-neighbour stitch, dedup by sorted index pair
 *   6. widen k until |edges| ≥ 40                          —  edge floor
 *   7. drop uniformly-random surplus until |edges| ≤ 240   —  edge cap
 *
 * All `rng` consumption order matches `scripts/motif.js`, so the same seed
 * yields the same node/edge set as the runtime canvas.
 *
 * @param {number} seed
 * @param {number} density
 * @returns {{ nodes: Array<{x:number,y:number}>, edges: Array<{a:any,b:any}> }}
 */
function buildMotifGraph(seed, density) {
  const rng = mulberry32(seed);
  const n = clamp(Math.round(30 + density * 90), 30, 120);
  const k = density < 0.5 ? 2 : density < 0.85 ? 3 : 4;

  const pts = poissonDisk(n, 0.85 / Math.sqrt(n), rng);
  while (pts.length < 30) pts.push({ x: rng(), y: rng() });

  const nodes = pts.map((p) => ({ x: p.x, y: p.y }));

  const N = nodes.length;
  const seen = new Set();
  const edges = [];
  const indexOf = new Map();
  for (let i = 0; i < N; i++) indexOf.set(nodes[i], i);

  const addNeighbours = (kk) => {
    for (let i = 0; i < N; i++) {
      const ni = nodes[i];
      const neighbours = kNearest(nodes, ni, kk);
      for (let p = 0; p < neighbours.length; p++) {
        const m = neighbours[p];
        const j = indexOf.get(m);
        const a = i < j ? i : j;
        const b = i < j ? j : i;
        const key = a * N + b;
        if (seen.has(key)) continue;
        seen.add(key);
        edges.push({ a: nodes[a], b: nodes[b] });
      }
    }
  };

  addNeighbours(k);

  // Widen k until we cross the 40-edge floor or exhaust available neighbours.
  let kk = k + 1;
  while (edges.length < 40 && kk <= N - 1) {
    addNeighbours(kk);
    kk++;
  }

  // Drop uniformly-random surplus down to the 240-edge cap.
  while (edges.length > 240) {
    const idx = Math.floor(rng() * edges.length);
    edges.splice(idx, 1);
  }

  return { nodes, edges };
}

/** Largest edge length, used to scale signal-strength stroke width. */
function computeMaxDist(edges) {
  let m = 0;
  for (let i = 0; i < edges.length; i++) {
    const e = edges[i];
    const dx = e.a.x - e.b.x;
    const dy = e.a.y - e.b.y;
    const d = Math.hypot(dx, dy);
    if (d > m) m = d;
  }
  return m || 1;
}

// ── SVG emission ───────────────────────────────────────────────────────────

/** Format a unit-coordinate component as a 2-decimal viewBox-space number. */
const fx = (u, scale) => (u * scale).toFixed(2);

/** Format stroke-width to 2 decimals, no trailing zero pile-up. */
const fw = (w) => Number(w.toFixed(2)).toString();

/**
 * Build the SVG inner markup for `(nodes, edges)`. Lines come first so nodes
 * paint on top, matching the z-order of the runtime canvas (which clears,
 * then strokes edges, then fills nodes).
 *
 * Per-element inline `style` references design system tokens with documented
 * fallbacks — token-only paint. Wrapping `<g>` carries the
 * background opacity envelope.
 */
function buildSvgInner(nodes, edges) {
  const maxDist = computeMaxDist(edges);

  const lines = edges
    .map((e) => {
      const dx = e.a.x - e.b.x;
      const dy = e.a.y - e.b.y;
      const d = Math.hypot(dx, dy);
      // Same signal-strength formula as `scripts/motif.js`, dpr = 1.
      const sw = lerp(1.4, 0.4, d / maxDist);
      return (
        `      <line x1="${fx(e.a.x, W)}" y1="${fx(e.a.y, H)}"` +
        ` x2="${fx(e.b.x, W)}" y2="${fx(e.b.y, H)}"` +
        ` stroke-width="${fw(sw)}"` +
        ` style="stroke: var(--color-line, #c9bfb1)" />`
      );
    })
    .join('\n');

  const circles = nodes
    .map(
      (n) =>
        `      <circle cx="${fx(n.x, W)}" cy="${fx(n.y, H)}" r="2"` +
        ` style="fill: var(--color-accent-2, #c98c5a)" />`,
    )
    .join('\n');

  return (
    `\n    <g opacity="${BG_ALPHA}">\n` +
    `${lines}\n` +
    `${circles}\n` +
    `    </g>\n  `
  );
}

// ── HTML injection ─────────────────────────────────────────────────────────

/**
 * Replace the children of the `<svg class="ap-motif-fallback">` element while
 * preserving its existing opening tag (so attributes set in `index.html`* `aria-hidden`, `hidden`, `viewBox`, `xmlns`are kept verbatim).
 *
 * Throws if the element is missing, the regex is ambiguous, or the file is
 * already populated with non-comment content (so re-running the script does
 * not silently double-write or shadow a previous run).
 */
function injectSvg(html, svgInner) {
  // Capture: (1) full opening tag, (2) inner content. The element is never
  // self-closing in `index.html` (it always has explicit closing `</svg>`),
  // so we don't need to handle the `/>` form.
  const re = /(<svg\s+class="ap-motif-fallback"[^>]*>)([\s\S]*?)<\/svg>/i;
  const match = html.match(re);
  if (!match) {
    throw new Error(
      'Could not find <svg class="ap-motif-fallback"> in index.html. ' +
        'Has task 3.2 (hero markup) been run?',
    );
  }
  const [, openTag] = match;
  return html.replace(re, `${openTag}${svgInner}</svg>`);
}

// ── Entry point ────────────────────────────────────────────────────────────

async function main() {
  const here = dirname(fileURLToPath(import.meta.url));
  const repoRoot = resolve(here, '..');
  const indexPath = resolve(repoRoot, 'index.html');

  const html = await readFile(indexPath, 'utf8');
  const { nodes, edges } = buildMotifGraph(FIXED_SEED, DENSITY);

  // Sanity-check  bounds before we touch the file.
  if (nodes.length < 30 || nodes.length > 120) {
    throw new Error(
      `Node count out of bounds: ${nodes.length} ∉ [30, 120].`,
    );
  }
  if (edges.length < 40 || edges.length > 240) {
    throw new Error(
      `Edge count out of bounds: ${edges.length} ∉ [40, 240].`,
    );
  }

  const svgInner = buildSvgInner(nodes, edges);
  const updated = injectSvg(html, svgInner);
  await writeFile(indexPath, updated, 'utf8');

  console.log(
    `Rendered SVG motif (seed=0x${FIXED_SEED.toString(16)}, density=${DENSITY}): ` +
      `${nodes.length} nodes, ${edges.length} edges → ` +
      `${relative(repoRoot, indexPath)}`,
  );
}

main().catch((err) => {
  console.error('✗ render-svg-motif crashed:', err);
  process.exit(1);
});
